window.ETC = window.ETC || {};

window.ETC.igudziai = [
  {"id": 1, "grupe": "K", "pav": "PCC perėmimas: MARCH-PAWS iš naujo ir problemų sąrašas", "lygis": "CLS", "fazes": ["STAB"], "aprasas": "PCC prasideda, kai evakuacija vėluoja ir sužeistojo poreikiai viršija tai, ką galima suteikti dabar. Pirmiausia – visų atliktų TCCC intervencijų patikra, tada išsami apžiūra ir problemų sąrašas, iš kurio sudaromas priežiūros planas.", "zingsniai": ["Perkelkite į apsaugotą, šiltą, apšviestą vietą; izoliuokite nuo žemės.", "Perimkite MIST ir kortelę (DD 1380); užrašykite traumos ir turniketų laikus.", "M – kiekvienas turniketas, tamponavimas, tvarstis: ar kraujavimas sustojęs, ar niekas nepasislinko (#27).", "A, R – kvėpavimo takai, krūtinės lipdukai, NDC kateteriai; SpO₂ ≥ 92 % (#11, #12).", "C – radialinis pulsas, sąmonė, AKS; šokas – gaivinimas krauju (#6, #7).", "H – apvalkalas sausas ir sandarus; galvos trauma – neurologinė patikra (#31, #32).", "P, A, W, S – skausmas, antibiotikas, žaizdos, įtvarai: kas padaryta ir kada.", "Išsami apžiūra (#4) → problemų sąrašas → planas: kas stebi, kas ir kada daroma, ko trūksta. Evakuacijos ir telekonsultacijos prašykite iš karto (#36)."], "esme": ["„Padarei – patikrink dar kartą“: PCC nepakeičia TCCC, o jį tęsia.", "Laukimas – aktyvi priežiūra: vertinti → stabilizuoti → stebėti → tęsti → perduoti."], "klaidos": ["Pasitikima ankstesniu vertinimu – nepastebimas atsinaujinęs kraujavimas ar pasislinkęs turniketas.", "Evakuacijos ir telekonsultacijos prašoma tik pablogėjus."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021) – principai, MARC2H3-PAWS-L", "Kuopos paskaita „Slauga taktinėje aplinkoje (PCC)“ (2026-09-21)"]},
  {"id": 2, "grupe": "K", "pav": "Gyvybinių rodiklių stebėjimas ir tendencijos", "lygis": "CLS", "fazes": ["STAB", "VAL", "PAROS"], "aprasas": "PCC metu svarbus ne vienas skaičius, o dinamika. Dažnis priklauso nuo būklės; apmokytas CLS stebi, kai medikas užimtas ar ilsisi.", "zingsniai": ["Dažnis: kritinė – kas 15–30 min, kol stabilizuojasi; rimta, bet stabili – kas 4 val.; nekritinė – kas 12 val.", "Po gaivinimo – kas 15 min; stabiliai > 2 val. – kas 30–60 min.", "Eilė – nuo ankstyviausių šoko požymių: sąmonė, KD, pulsas, periferinis pulsas, AKS; taip pat SpO₂ ir temperatūra.", "Įranga: minimum – AKS matuoklis, stetoskopas, pulsoksimetras; geriau – kapnometrija; geriausia – monitorius su nuolatiniu rodymu ir kapnografija.", "Temperatūra: minimum – pagal grafiką; geriau – nuolatinis kaktos indikatorius; geriausia – nuolatinė vidinė.", "Kiekvieną matavimą su laiku – į stebėjimo lapą (#3); palyginkite su ankstesniu.", "Blogėja (pulsas > sAKS, SpO₂ < 92 %, mažėja diurezė, krinta GKS) – iš naujo MARCH, medikas, telekonsultacija (#36)."], "esme": ["„Koks buvo prieš valandą? Koks dabar? Kas pasikeitė?“", "Šoko indeksas (pulsas ÷ sAKS) > 1 – skubios telekonsultacijos kriterijus."], "klaidos": ["Skaičiai be laiko – tendencijos nematyti.", "Matavimai retinami, nes sužeistasis „ramus“ – sedacija ir šokas tai maskuoja."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "JTS CPG „Damage Control Resuscitation in PFC“ (ID 73, 2018)", "JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "JTS CPG „Telemedicine Guidance in the Deployed Setting“ (ID 94, 2023)"]},
  {"id": 3, "grupe": "K", "pav": "PCC stebėjimo lapas ir dokumentavimas", "lygis": "CLS", "fazes": ["STAB", "VAL", "PAROS", "EVAK"], "aprasas": "Kas neužrašyta – to nėra: be laikų ir tendencijų neįmanoma įvertinti eigos ir saugiai perduoti. Lygiai: minimum – kortelė DD 1380; geriau – PCC stebėjimo lapas; geriausia – lapas ir slaugos grafikas, po perdavimo – AAR.", "zingsniai": ["Kai kortelės laukeliai užpildyti, o evakuacija negreit – pereikite prie stebėjimo lapo; kortelė lieka pritvirtinta.", "Su laiku: gyvybiniai rodikliai, GKS ir vyzdžiai, skausmas, RASS (sedatuotam).", "Įvesta ir išskirta (#10): kritinei – kas 1–2 val., nekritinei – per dieną; suma kas 24 val.", "Vaistai: pavadinimas, dozė, būdas, laikas, poveikis, kitos dozės laikas.", "Intervencijos ir priežiūra: turniketai ir konversija, linijos, kateteris, tvarsčiai, vartymas.", "Problemų sąrašą ir planą atnaujinkite po kiekvieno pakartotinio vertinimo.", "Prieš telekonsultaciją ir perdavimą – lapą nufotografuokite ir nusiųskite (#36, #38)."], "esme": ["„Jei informacija liko tik mano galvoje – ji gali būti prarasta kartu su manimi.“", "Užrašykite, kas suteikė pagalbą – kita grandis galės susisiekti."], "klaidos": ["Rašoma vėliau „iš atminties“ – prarandami laikai ir dozės.", "Lapas atskiriamas nuo sužeistojo."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021) – dokumentavimas", "JTS CPG „Damage Control Resuscitation in PFC“ (ID 73, 2018)", "JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "PFC Documentation: Telemedical Consultation Guide (2023)", "Kuopos paskaita „Slauga taktinėje aplinkoje (PCC)“ (2026-09-21)"]},
  {"id": 4, "grupe": "K", "pav": "Išsami apžiūra ir problemų sąrašas", "lygis": "CMC", "fazes": ["STAB", "VAL", "PAROS"], "aprasas": "Suvaldžius gyvybei pavojingas būkles, kruopšti apžiūra nuo galvos iki kojų randa praleistus sužalojimus. Iš jos sudaromas problemų sąrašas – priežiūros plano ir telekonsultacijos pagrindas.", "zingsniai": ["Atidenkite dalimis, kitas dalis laikykite uždengtas.", "Galva: žaizdos, kaukolės pamato lūžio požymiai, GKS, vyzdžiai; akys – regėjimas (raidės, pirštai, judesys, šviesa), standus skydelis įtarus penetraciją.", "Krūtinė: kvėpavimo garsai abiejose pusėse, simetrija, lipdukai, NDC kateteriai.", "Pilvas ir dubuo: skausmingumas, pūtimasis, dubens diržas; šlapimo kiekis ir spalva.", "Galūnės: žaizdos, distalinis pulsas, jutimai, judesiai, įtvarai, kompartmentai (#28).", "Nugara – verčiant (#19); oda – pragulų požymiai.", "Prieigos ir vamzdeliai: vieta, data, veikimas (#8).", "Problemų sąrašas: problema → veiksmas → atsakingas. Kartokite pasikeitus būklei ir prieš perdavimą."], "esme": ["Ultragarsas ir greitieji tyrimai tik papildo apžiūrą.", "Sedatuotas ar sutrikusios sąmonės sužeistasis skausmo nepasakys – apžiūrėkite dažniau."], "klaidos": ["Neapžiūrima nugara ir pažastys.", "Radiniai neperkeliami į planą."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "PFC WG „10 Essential Core Capabilities for PFC“ (2015)", "JTS „Ocular Injuries and Vision-Threatening Conditions in PFC“ (infografikas, 2026)"]},
  {"id": 5, "grupe": "K", "pav": "Komanda ir resursai PCC metu", "lygis": "CLS", "fazes": ["STAB"], "aprasas": "PCC – sistema: žmonės, priemonės, ryšys, logistika ir evakuacija. Mažiau resursų reiškia ne mažiau planavimo, o daugiau prioritetų ir kontrolės.", "zingsniai": ["Lyderis paskiria: kas atsako už sužeistąjį, kas stebi, kas valdo resursus, kas palaiko ryšį dėl evakuacijos, kas dokumentuoja.", "Inventorizacija: kraujas ir skysčiai, vaistai, deguonis, tvarsčiai, baterijos, vanduo, maistas, šiluma – kiek valandų užteks.", "Klauskite: kiek sužeistųjų, kiek laiko iki evakuacijos, kada papildymas, kas bus, jei priemonę sunaudosime dabar.", "Ryšio PACE planas (pagrindinis, alternatyvus, atsarginis, avarinis) – ir priežiūrai, ir technikai.", "Pamainos ir poilsis; apmokyti CLS perima slaugos užduotis.", "Eskalavimo kriterijai: kada kviesti mediką, kada telekonsultaciją, kada keisti evakuacijos skubumą.", "Atsarginė vieta ir evakuacijos iš punkto planas – punktas gali būti atakuojamas."], "esme": ["„Paprasčiau – geriau.“ Triažas ir resursų paskirstymas PCC metu – nuolatinis procesas.", "„Herojiškai dirbti iki išsekimo“ – ne taktika."], "klaidos": ["Neskaičiuojama, kiek valandų užteks kraujo, deguonies ir baterijų.", "Visi prie paciento, niekas – prie ryšio ir evakuacijos."], "vaizdai": [], "video": [], "saltiniai": ["Kuopos paskaita „Slauga taktinėje aplinkoje (PCC)“ (2026-09-21)", "JTS CPG „Telemedicine Guidance in the Deployed Setting“ (ID 94, 2023) – PACE", "JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)"]},
  {"id": 6, "grupe": "G", "pav": "Šokas PCC metu: gaivinimas ir jo tikslai", "lygis": "CMC", "fazes": ["STAB", "VAL"], "aprasas": "Gaivinimo principai tie patys kaip TCCC: sustabdyti kraujavimą ir perpilti kraują. PCC metu svarbu laiku sustoti ir atpažinti, ar sužeistasis reaguoja į gaivinimą.", "zingsniai": ["Šoko požymiai: sAKS < 100, pulsas > 100, šaltos galūnės, lėtas kapiliarų prisipildymas, sutrikusi sąmonė (be galvos traumos), kraujavimas iš dūrio vietų.", "Pirmiausia – visi kraujavimo šaltiniai (#27); TXA ≤ 3 val. nuo sužeidimo.", "Kraujas: pilnas kraujas → plazma : eritrocitai : trombocitai 1 : 1 : 1 → 1 : 1 → plazma ar eritrocitai; kristaloidai – tik paskutinė išeitis (#7).", "Kalcis po pirmojo vieneto, toliau – po kas 4 vienetų.", "Tikslas: minimum – čiuopiamas radialinis pulsas ar gerėjanti sąmonė; geriau – sAKS > 90; geriausia – sAKS 100–110 mm Hg. Galvos trauma – sAKS > 110 (#32).", "Pasiekus tikslą – gaivinimą nutraukite; toliau palaikomieji skysčiai ar gėrimas (#9), diurezė > 0,5 ml/kg/val. (#10).", "Pagerėjo ir vėl blogėja – praleistas kraujavimas, hipotermija, acidozė; nereaguoja – abipusė dekompresija, tamponada; telekonsultacija (#36).", "Hipotenzija išlieka po kraujo ir kraujavimo kontrolės – vazopresorius tik pagal protokolą ar telekonsultaciją."], "esme": ["Trys keliai: reaguoja, reaguoja trumpam, nereaguoja. Ar tęsti – spręskite su telekonsultacija.", "Kraujas veiksmingiausias per ~30 min nuo sužeidimo; kristaloidai blogina koaguliopatiją."], "klaidos": ["Gaivinama kristaloidais, nors yra kraujo ar donorų.", "Pasiekus tikslą pilama toliau „dėl visa ko“."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Damage Control Resuscitation in PFC“ (ID 73, 2018)", "JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "TCCC gairės 2026-05-01"]},
  {"id": 7, "grupe": "G", "pav": "Pilno kraujo perpylimas lauke (gyvasis kraujo bankas)", "lygis": "CMC", "fazes": ["STAB", "VAL"], "aprasas": "Pilnas kraujas – pirmo pasirinkimo produktas hemoraginiam šokui. Gyvasis kraujo bankas – iš anksto ištirti donorai padalinyje. Perpila tik apmokytas personalas, gebantis atpažinti ir gydyti transfuzijos reakcijas.", "zingsniai": ["Pirmenybė: šaltai laikytas mažo titro O pilnas kraujas → iš anksto ištirtų donorų šviežias O kraujas → grupei tapatus kraujas.", "Iš anksto: O grupės donorų titrai (mažas titras – IgM anti-A ir anti-B < 1:256), infekcijų tyrimai kas 90–120 d., donorų sąrašas.", "Prieš perpylimą paimkite sužeistojo kraujo mėginį vėlesniam grupės nustatymui.", "Grupei tapatus kraujas – tik patvirtinus grupę Eldon kortele donorui ir gavėjui (geriausia – du žmonės, dvi kortelės). Kariniu ženkleliu nesiremkite. Chaose – O grupė visiems.", "Iš donoro paprastai 1 vienetas; paėmus 2 – svarstykite donorą evakuoti kartu.", "Šviežias kraujas kambario temperatūroje – sunaudoti per 24 val. arba atšaldyti per 8 val.", "Pilkite per šildytuvą; kraujo ir vaistų viena linija neleiskite. Po pirmo vieneto – kalcis.", "Reakcija (karščiavimas, šaltkrėtis, bėrimas, dusulys, hipotenzija) – stabdykite, praneškite. Užrašykite donorą, grupę, laiką."], "esme": ["Liofilizuota plazma tinka pradėti gaivinimą, kol ruošiamas kraujas – ją galima visoms grupėms.", "Iš mirusio sužeistojo kraujo neimkite."], "klaidos": ["Grupė nustatoma pagal karinį ženklelį.", "Paimama per daug vienetų iš vieno donoro ir jis nebegali kovoti."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Damage Control Resuscitation in PFC“ (ID 73, 2018)", "JTS CPG „Whole Blood Transfusion“ (ID 21)", "TCCC gairės 2026-05-01"]},
  {"id": 8, "grupe": "G", "pav": "IV ir IO prieigų priežiūra", "lygis": "CMC", "fazes": ["STAB", "VAL", "PAROS"], "aprasas": "PCC metu prieiga turi veikti paromis: ją reikia tikrinti, plauti ir laiku keisti. Užsikimšusi prieiga dažniausiai paaiškėja tada, kai jos labiausiai reikia.", "zingsniai": ["Kas 4 val.: vieta, tvirtinimas, praeinamumas, žymėjimas.", "Praplaukite 0,9 % NaCl: minimum kas 8 val., geriausia kas 4 val.; ≥ 2 kateterio tūriai (periferiniam ~5 ml); po kiekvieno vaisto.", "Patinimas, skausmas, paraudimas dūrio vietoje – kateterį šalinkite.", "Periferinį keiskite tik dėl infekcijos, užsikimšimo ar infiltracijos.", "IO pašalinkite po 24 val. (sunkiai randamai venai – iki 48 val.).", "Sistemos: nuolatinė – kas 7 d.; protarpinė ir antrinė – kas 24 val.; kraujo – po kas 4 vienetų.", "Pradėti švirkštai: paženklinti (data, laikas), tik vienam sužeistajam, po 24 val. – išmesti.", "Kraujo ir vaistų viena linija neleiskite; kalcio ir ceftriaksono – ne kartu toje pačioje linijoje."], "esme": ["IO – laikina: kuo anksčiau pakeiskite IV.", "Kalcio ar noradrenalino ekstravazacija sukelia nekrozę – prieš leidžiant patikrinkite padėtį."], "klaidos": ["Nenaudojama linija neplaunama.", "IO paliekama ilgiau nei 24–48 val."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "JTS CPG „Damage Control Resuscitation in PFC“ (ID 73, 2018)"]},
  {"id": 9, "grupe": "G", "pav": "Palaikomieji skysčiai ir rehidracija per burną", "lygis": "CMC", "fazes": ["VAL", "PAROS"], "aprasas": "Pasiekus gaivinimo tikslus, skysčiai skiriami poreikiui patenkinti. Sąmoningas ir nevemiantis geria; intubuotam ar sedatuotam – IV / IO.", "zingsniai": ["Poreikis ramybėje ~2,1–2,6 l per parą (~100–125 ml/val.); daugiau – nudegimai, žaizdos, viduriavimas, karštis.", "Per burną: minimum – geriamasis vanduo; geriau – 1 l vandens + ½ šaukštelio druskos + 5–6 šaukšteliai cukraus; geriausia – rehidratacijos druskos (ORS).", "Galima gerti tol, kol diurezė 0,3–0,5 ml/kg/val.", "IV / IO: paprastai 100–150 ml/val., titruojant pagal diurezę – papildomai prie gaivinimo skysčių.", "Tirpalas: 0,9 % NaCl (minimum) → Ringerio laktatas → Plasma-Lyte A (geriausia).", "Diurezė mažėja – įvertinkite kitus netekimus (vėmimas, viduriavimas, nudegimai, prakaitas, NPWT).", "Visa, kas įvesta ir išskirta – į lapą (#3, #10)."], "esme": ["Laisvo vandens (tik vanduo dideliais kiekiais, 5 % gliukozė) venkite – hiponatremija.", "Šlapimo spalva hidratacijos patikimai neparodo – matuokite kiekį."], "klaidos": ["IV skysčiai sąmoningam, kuris gali gerti – eikvojami ištekliai.", "Geriamas tik vanduo."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)"]},
  {"id": 10, "grupe": "G", "pav": "Šlapimo kateteris ir diurezė", "lygis": "CMC", "fazes": ["STAB", "VAL", "PAROS"], "aprasas": "Diurezė – vienas geriausių gaivinimo pakankamumo rodiklių lauke. Šokui, nudegimams, suspaudimo sindromui ir sedatuotam – matuoti kas valandą.", "zingsniai": ["Galintis šlapintis – į graduotą indą (pvz., Nalgene butelį); kas valandą – Foley kateteris.", "Įveda apmokytas, aseptiškai; kraujas šlaplės angoje – nekiškite, praneškite gydytojui.", "Maišas žemiau šlapimo pūslės, vamzdelis be sulenkimų, pritvirtintas prie šlaunies.", "Priežiūra – ne rečiau kaip kas 24 val., po tuštinimosi, kaupiantis išskyroms.", "Maišą ištuštinkite kas 24 val. ar prisipildžius; kiekį užrašykite.", "Tikslai: ~0,5 ml/kg/val. (≥ 30 ml/val.); be kateterio – > 180 ml per 6 val.; nudegimai – 30–50 ml/val. (#33); suspaudimo sindromas – 100–200 ml/val. (#35).", "Šalinkite kuo anksčiau; vyrui – išorinis kateteris (gaivinant gali rodyti per mažai)."], "esme": ["Rudas, raudonas ar juodas šlapimas – mioglobinas (#35).", "Mažėjanti diurezė – ankstyvas blogėjimo ženklas: perfuzija, skysčiai, kateterio praeinamumas."], "klaidos": ["Maišas ant pilvo ar neštuvų – šlapimas teka atgal.", "Ištuštinant kiekis neužrašomas."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "JTS CPG „Damage Control Resuscitation in PFC“ (ID 73, 2018)", "JTS CPG „Burn Wound Management in PFC“ (tccc.org.ua, 2023)", "JTS CPG „Crush Syndrome in PFC“ (tccc.org.ua, 2023)"]},
  {"id": 11, "grupe": "A", "pav": "Kvėpavimo takų priežiūra ir atsiurbimas", "lygis": "CMC", "fazes": ["STAB", "VAL", "PAROS"], "aprasas": "Ilgai laukiant kvėpavimo takai užsikemša išskyromis ir krauju, vamzdeliai pasislenka. Vertinama pagal SpO₂, EtCO₂ ir kvėpavimo pastangas.", "zingsniai": ["Burnos atsiurbimas pagal poreikį: minimum – 60 ml švirkštas su ~25 cm IV sistemos vamzdeliu; geriausia – standus antgalis ir siurblys; mažiausias veiksmingas slėgis, stebint SpO₂.", "Vamzdelio atsiurbimas – tik esant indikacijai (gausios ar spalvotos išskyros, krentanti oksigenacija, įtariamas kamštis); steriliai.", "Prieš tai – FiO₂ 100 % 30–60 s (jei toleruoja); siurbkite tik traukdami, ≤ 15 s, tarp kartų ≥ 30 s.", "Įkvėpimo trauma – atsiurbti ~kas valandą, su 3–5 ml NaCl (#33).", "Manžetės slėgis – manometru, ~20 mm Hg; tikrinkite periodiškai (#14).", "Galvūgalis ~30°, jei leidžia būklė."], "esme": ["EtCO₂ padidėjimas ar kreivės pokytis – galimai užsikimšęs vamzdelis."], "klaidos": ["Siurbiama per ilgai – desaturacija.", "Rutininis atsiurbimas be indikacijos."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "JTS CPG „Burn Wound Management in PFC“ (tccc.org.ua, 2023)"]},
  {"id": 12, "grupe": "A", "pav": "Ilgalaikė ventiliacija maišu su PEEP vožtuvu ir deguonis", "lygis": "CMC", "fazes": ["STAB", "VAL", "YPAT"], "aprasas": "Kai nėra ventiliatoriaus, sužeistasis ventiliuojamas rankiniu maišu valandas. Tai išteklių ir žmonių problema – planuokite iš anksto.", "zingsniai": ["Kiekviename ambu maiše – PEEP vožtuvas; kvėpavimo takams – NPA, jei nėra kitos priemonės.", "Tikslai: SpO₂ ≥ 92 %; EtCO₂ 35–45 mm Hg (galvos trauma – 35–40) (#32).", "Deguonis: minimum – PEEP vožtuvas; geriau – deguonies koncentratorius; geriausia – portatyvus ventiliatorius su deguonimi (#13).", "Galvos trauma be EtCO₂ – 10 įpūtimų/min.", "Įpūtimas lėtas, kol pakyla krūtinė; venkite hiperventiliacijos.", "Ventiliuojantys keičiasi; tendencijas rašykite (#3).", "Ilgai ventiliuojamam – evakuacija su ventiliacija (9-Line 4 eilutė – D)."], "esme": ["Hiperventiliacija rankiniu maišu mažina smegenų perfuziją."], "klaidos": ["Neuždedamas PEEP vožtuvas.", "Vienas žmogus ventiliuoja valandų valandas."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "PFC WG „10 Essential Core Capabilities for PFC“ (2015)", "TCCC gairės 2026-05-01"]},
  {"id": 13, "grupe": "A", "pav": "Portatyvus ventiliatorius: pradžia ir trikčių paieška", "lygis": "CPP", "fazes": ["VAL", "PAROS", "YPAT"], "aprasas": "Ventiliatorius atlaisvina žmones ir tiksliau palaiko ventiliaciją. Mechaninė ventiliacija ir sedacija PCC metu gali tęstis iki 96 val. – planuokite deguonį, energiją ir vaistus.", "zingsniai": ["Prieš prijungdami: kvėpavimo takai užtikrinti, HME filtras, baterija įkrauta, grandinė ir filtras patikrinti.", "Pradžia: tūrio ar slėgio kontrolė; kvėpavimo tūris 6–8 ml/kg numatomo kūno svorio (nuo 8 – per 2 val. iki 6); PEEP ≥ 5 cm H₂O; dažnis – pagal EtCO₂.", "FiO₂ – mažiausias, kuriuo SpO₂ ≥ 92 %; deguonies srautą – pagal gamintojo lentelę.", "Įkvėpimo slėgis ≤ 30–35 cm H₂O.", "Patikrinkite atjungimo ir didžiausio slėgio signalus.", "Staiga blogėja – atjunkite, ventiliuokite maišu, tikrinkite DOPE: pasislinkęs, užsikimšęs vamzdelis, pneumotoraksas, įrangos gedimas.", "Sedacija pagal RASS (#17); galvūgalis ~30°; burnos priežiūra kas 4 val. (#20); zondas (#15)."], "esme": ["Tūris skaičiuojamas pagal numatomą (ūgio), ne faktinį svorį."], "klaidos": ["Signalai išjungiami dėl triukšmo.", "Pablogėjus ieškoma gedimo ventiliatoriuje, o ne vamzdelyje."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Management of Acute Respiratory Failure“ (2014)", "JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "JTS CPP įgūdžio kortelė 26 „Automated Ventilation“ (2023)"]},
  {"id": 14, "grupe": "A", "pav": "Intubacinio ar krikotiroidotomijos vamzdelio priežiūra", "lygis": "CPP", "fazes": ["VAL", "PAROS", "YPAT"], "aprasas": "Atsitiktinė ekstubacija lauke – gyvybei pavojinga. Vamzdelio padėtį, tvirtinimą ir manžetę tikrinkite reguliariai ir po kiekvieno perkėlimo.", "zingsniai": ["Po kiekvieno perkėlimo: EtCO₂ kreivė, kvėpavimo garsai, gylio žymė.", "Tvirtinkite medvilnine juosta, ne lipnia juostele (ypač nudegusiam veidui).", "Manžetę pripūskite 10 ml švirkštu, atleiskite stūmoklį, kad slėgis išsilygintų; tikslas ~20 mm Hg manometru.", "HME filtras ir uždaras atsiurbimas, jei yra (#11).", "Zondas skrandžiui dekompresuoti (#15).", "Burnos priežiūra kas 4 val., lūpų balzamas (#20).", "Sedacijos lygis – RASS; pradžioje – kas 5 min (#17)."], "esme": ["Verčiant vienas žmogus laiko vamzdelį ir skaičiuoja."], "klaidos": ["Manžetės slėgis „pagal pirštus“.", "Juostelė per nudegimą."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "JTS CPG „Burn Wound Management in PFC“ (tccc.org.ua, 2023)", "JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)"]},
  {"id": 15, "grupe": "A", "pav": "Zondas (NG / OG) ir maitinimas per zondą", "lygis": "CMC", "fazes": ["PAROS", "YPAT"], "aprasas": "Zondas dekompresuoja skrandį (ventiliacija, nudegimai) ir leidžia maitinti intubuotą ar sedatuotą sužeistąjį, kai evakuacija vėluoja paromis.", "zingsniai": ["Intubuotam ar sedatuotam, laikomam 48–72 val., – maitinimo zondas.", "Įtariamas veido ar kaukolės pamato lūžis – tik per burną (OG).", "Padėtis: jei galima – rentgenas; kitaip – įpūskite oro klausydami viršutinėje kairėje pilvo dalyje ir aspiruokite skrandžio turinį ar tulžį.", "Geriau: trofinis maitinimas 10–20 ml/val., kas 4 val. praplauti 30 ml vandens.", "Geriausia: kas 4 val. +10 ml/val. iki 60 ml/val.; daug baltymų turintis mišinys.", "Mišinio nėra – ilgo galiojimo (UHT) pienas, galima su baltymų milteliais iš MRE.", "Maitinant galvūgalis ~30°."], "esme": ["Nemaitinamam gliukozę matuokite kas 8 val.; < 4,4 mmol/l – gydyti iš karto."], "klaidos": ["Zondas per nosį esant kaukolės pamato lūžiui.", "Maitinama nepatikrinus padėties."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "JTS CPG „Burn Wound Management in PFC“ (tccc.org.ua, 2023)"]},
  {"id": 16, "grupe": "S", "pav": "Ketaminas: nuskausminimas PCC metu", "lygis": "CMC", "fazes": ["STAB", "VAL", "PAROS"], "aprasas": "PCC metu skausmas tęsiasi paromis: titruokite po mažiau, kartokite dažniau. Pirmiausia nuskausminkite, tik tada sedatuokite.", "zingsniai": ["Prieš pirmą dozę: AVPU / GKS ir skausmas (0–10) – į lapą; nuginkluoti.", "Pirmenybė IV / IO; į nosį PCC metu – vengti.", "Dozė ir kartojimas – Vaistai: Ketaminas (TCCC 2026).", "Kartu – paracetamolis ir meloksikamas, jei gali nuryti ir nėra kontraindikacijų.", "Stebėkite KD, SpO₂, AKS; KD < 10 – stabdykite, atverkite takus, ventiliuokite (#18).", "Pykinimas – ondansetronas.", "Skausmas nuolatinis – ketamino infuzija (CPP, #17), telekonsultacija.", "Prieš žaizdų priežiūrą: IV vaistą – 15–30 min, per burną – ≥ 60 min prieš (#25)."], "esme": ["Šokas ar kvėpavimo distresas – vengti AKS ir kvėpavimą slopinančių vaistų; ketaminas – pirmo pasirinkimo.", "Ketaminas, opioidai ir benzodiazepinai stiprina vienas kitą – kiekvieno reikia mažiau."], "klaidos": ["Didelė vienkartinė dozė vietoj titravimo.", "Neužrašyta pradinė neurologija – vėliau neaišku, ar blogėja galva."], "vaizdai": [], "video": [], "saltiniai": ["TCCC gairės 2026-05-01", "JTS CPG „Analgesia and Sedation Management during PFC“ (tccc.org.ua, 2023)", "JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)"]},
  {"id": 17, "grupe": "S", "pav": "Ketamino infuzija ir sedacija (RASS)", "lygis": "CPP", "fazes": ["VAL", "PAROS", "YPAT"], "aprasas": "Ilgai sedacijai ir sunkiai valdomam skausmui JTS rekomenduoja ketamino infuziją, prireikus papildant midazolamu. Sprendžia CPP ar gydytojas, geriausia – su telekonsultacija.", "zingsniai": ["Prisotinamoji dozė – 1 mg/kg IV / IO per 60 s.", "Tirpalas: 750 mg į 250 ml 0,9 % NaCl = 3 mg/ml; viename maiše – tik vienas vaistas.", "Neintubuotam – 1 mg/kg/val.; intubuotam – 1–2 mg/kg/val. (80 kg, 1 mg/kg/val. ≈ 27 ml/val.).", "Titruokite po 0,25 mg/kg/val.: proveržio skausmas 2 kartus per valandą – didinti; 2 val. be proveržio – mažinti. Pilnas poveikis – per ~1 val.", "Didesnėms dozėms (> 0,3 mg/kg) – midazolamas 0,5–2 mg IV / IO emergencijos reakcijai mažinti.", "RASS: 0 budrus ir ramus; −1 mieguistas; −2 lengva; −3 vidutinė; −4 gili sedacija; −5 nereaguoja. Neintubuotam – ramus, pažadinamas; intubuotam – gili sedacija, sinchronija su ventiliatoriumi.", "Stebėjimas: minimum – AKS, stetoskopas, SpO₂; geriau – kapnografija. Rodikliai, GKS, skausmas – kas 5 min iki tikslo, toliau kas 15 min."], "esme": ["Naloksonas ir maišas su kauke – visada po ranka (#18)."], "klaidos": ["Keli vaistai viename maiše.", "Greitis skaičiuojamas pagal ampulės, ne maišo koncentraciją."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Analgesia and Sedation Management during PFC“ (tccc.org.ua, 2023)", "JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)"]},
  {"id": 18, "grupe": "S", "pav": "Per gili sedacija ir kvėpavimo slopinimas", "lygis": "CMC", "fazes": ["VAL", "PAROS"], "aprasas": "Nuskausminimo tikslai PCC metu: KD > 12, EtCO₂ < 50 mm Hg, SpO₂ > 94 %, sAKS > 90 mm Hg. Rizika didžiausia šoke, nepakankamai gaivinus, esant galvos traumai ir derinant vaistus.", "zingsniai": ["Šoke standartines dozes mažinkite – vaistai gali sukelti kraujotakos kolapsą.", "Požymiai: KD < 10, krentantis SpO₂, kylantis EtCO₂, sunkiai pažadinamas.", "Stabdykite infuziją; „uostymo“ padėtis, NPA, ventiliacija maišu su PEEP.", "Opioido perdozavimas – naloksonas, titruojant po 40 mcg IV / IO, kol atsistato kvėpavimas, išlaikant nuskausminimą (Vaistai: Naloksonas).", "Naloksonas gali baigti veikti anksčiau nei opioidas – stebėkite.", "Po procedūrinės sedacijos – stebėkite ilgiau."], "esme": ["Benzodiazepinų su opioidais ar ketaminu neskirkite, nebent nurodė CPP ar gydytojas."], "klaidos": ["Po naloksono sužeistasis nestebimas – opioidas gali veikti ilgiau.", "Opioidai ir benzodiazepinai kartojami, nors KD jau retėja."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "JTS CPG „Analgesia and Sedation Management during PFC“ (tccc.org.ua, 2023)", "JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "TCCC gairės 2026-05-01"]},
  {"id": 19, "grupe": "N", "pav": "Vartymas ir pragulų prevencija", "lygis": "CLS", "fazes": ["VAL", "PAROS"], "aprasas": "Ant neštuvų ir be sąmonės pragulos atsiranda greitai. Vartymas kartu – proga apžiūrėti nugarą, odą, tvarsčius ir linijas.", "zingsniai": ["Vartykite ir tikrinkite paminkštinimą ne rečiau kaip kas 2 val.; ant kieto paviršiaus – kas 1 val.; be sąmonės – kas 1–2 val.", "Galvūgalis ~30°, jei leidžia būklė.", "Paminkštinkite: pakaušis, mentys, alkūnės, kryžkaulis, kulnai; atskirkite kelius, kulkšnis, alkūnes; po blauzdomis – atrama, kad kulnai būtų laisvi.", "Neblykštantis paraudimas – pažymėkite, atleiskite spaudimą, paminkštinkite.", "Oda sausa, ypač raukšlės; šlapią apatinį sluoksnį keiskite.", "Juosteles ir EKG elektrodus keiskite kas 24 val., jei yra priemonių.", "Įtariama stuburo trauma – verčiama kaip rąstas, saugant linijas ir vamzdelius."], "esme": ["Neštuvai – kietas paviršius: kas 1 val."], "klaidos": ["Sužeistasis paliekamas toje pačioje padėtyje visą naktį.", "Šildymo paketas ant spaudžiamos vietos (#31)."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "Kuopos paskaita „Slauga taktinėje aplinkoje (PCC)“ (2026-09-21)"]},
  {"id": 20, "grupe": "N", "pav": "Burnos, nosies ir akių priežiūra", "lygis": "CLS", "fazes": ["VAL", "PAROS"], "aprasas": "Burnos priežiūra mažina pneumonijos riziką; sedatuotam ar be sąmonės akys išdžiūsta ir pažeidžiama ragena.", "zingsniai": ["Sąmoningas valosi dantis kas 12 val.; be sąmonės – burną valykite ne rečiau kaip kas 4 val.", "Valykite ~1 min drėgna marle, ją keisdami; siurbimas – po ranka.", "Po to – lūpų balzamas; nosies priežiūra tais pačiais intervalais.", "Akys: saugokite nuo išdžiūvimo ir įbrėžimų; chirurginio lubrikanto (Surgilube) į akis nedėkite – toksiškas ragenai.", "Įtariamas atviras akies obuolys – standus skydelis, jokio spaudimo.", "Cheminis akies nudegimas – plauti ≥ 2 l arba kol pH 7."], "esme": ["Intubuotam burnos priežiūra – kas 4 val."], "klaidos": ["Burnos priežiūra pamirštama.", "Į akis tepama lubrikanto želė."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "JTS „Ocular Injuries and Vision-Threatening Conditions in PFC“ (infografikas, 2026)", "Kuopos paskaita „Slauga taktinėje aplinkoje (PCC)“ (2026-09-21)"]},
  {"id": 21, "grupe": "N", "pav": "Higiena ir odos priežiūra", "lygis": "CLS", "fazes": ["PAROS"], "aprasas": "Sausa ir švari oda – mažiau pragulų ir infekcijų. Prausti – ne rečiau kaip kas 24 val.", "zingsniai": ["Šiltas vanduo, švelnus muilas, marlė: nuo veido iki lytinių organų; kiekvienai daliai – švarus vanduo; panaudotos marlės atgal į dubenį nedėkite.", "Drėgnas servetėles prieš naudojant praskalaukite – daugelyje yra alkoholio.", "Be sąmonės – inkontinenciją tikrinkite kas 2 val.", "Kruopščiai nusausinkite, ypač raukšles; ilgus plaukus supinkite šone.", "Tvarsčius ir linijas prausdami apsaugokite plėvele.", "Kateterio priežiūra – tuo pačiu metu (#10)."], "esme": ["Sąmoningas prausiasi su pagalba – kuo daugiau pats."], "klaidos": ["Visas kūnas prausiamas viena marle."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "Kuopos paskaita „Slauga taktinėje aplinkoje (PCC)“ (2026-09-21)"]},
  {"id": 22, "grupe": "N", "pav": "Trombozės ir plaučių komplikacijų prevencija", "lygis": "CLS", "fazes": ["VAL", "PAROS"], "aprasas": "Imobilizacija paromis – trombozės ir pneumonijos rizika. Prevencija paprasta: kvėpavimo pratimai, judesiai, kompresija.", "zingsniai": ["Sąmoningas: lėtai giliai įkvėpti, sulaikyti 3–5 s, iškvėpti per sučiauptas lūpas – 10 kartų kas valandą būdraujant; daugėjant išskyrų – kosėti kas valandą.", "Kompresinės kojinės ar elastiniai tvarsčiai nuo pirštų į viršų; pirštai atidengti.", "Be sąmonės: kulkšnių judesiai ir blauzdų masažas – 10 kartų kas 2 val.", "Visi neriboti sąnariai – kas 8 val., 5–10 kartų.", "Sąmoningą sodinkite ant krašto 2–3 kartus per dieną; geriausia – sėdėti kėdėje ir vaikščioti su pagalba, jei saugu.", "Lūžusiai ar sunkiai sužalotai galūnei pratimų ir masažo nedarykite."], "esme": ["Kosulys ir gilus kvėpavimas – pigiausia pneumonijos prevencija."], "klaidos": ["Masažuojama sužalota galūnė."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "Kuopos paskaita „Slauga taktinėje aplinkoje (PCC)“ (2026-09-21)"]},
  {"id": 23, "grupe": "N", "pav": "Mityba ir gėrimas", "lygis": "CLS", "fazes": ["PAROS"], "aprasas": "Sąmoningas, galintis nuryti ir nevemiantis sužeistasis geria ir valgo – tai taupo IV skysčius ir padeda gyti. Nudegimai ir didelės žaizdos poreikį didina.", "zingsniai": ["Skatinkite gerti nuolat, ne pagal fiksuotą intervalą (~100–125 ml/val.).", "Tik vandens nepakanka – rehidratacijos tirpalas (#9).", "Maistas, baltymai ar papildai – kas 4–6 val., mažomis porcijomis (5–6 kartus per dieną).", "Tikslas: geriau – 50–70 % porcijos; geriausia – ≥ 75 %.", "Gėrimą ir maistą užrašykite (#3).", "Nemaitinamam – gliukozė kas 8 val., jei galima matuoti (#15).", "Karštyje – valgyti, kad nenetektų natrio."], "esme": ["Gerti skatinkite visą laiką – sužeistasis pats prašo per retai."], "klaidos": ["Vemiančiam duodama gerti – aspiracija."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "Kuopos paskaita „Slauga taktinėje aplinkoje (PCC)“ (2026-09-21)"]},
  {"id": 24, "grupe": "N", "pav": "Komfortas ir psichologinė parama", "lygis": "CLS", "fazes": ["VAL", "PAROS"], "aprasas": "Ilgas laukimas, skausmas, nežinomybė ir izoliacija didina stresą. Tai visos komandos, ne tik medikų, atsakomybė.", "zingsniai": ["Kalbėkite ramiai, paaiškinkite, kas vyksta.", "Prieš kiekvieną veiksmą – įspėkite.", "Išklausykite, palaikykite kontaktą; nepalikite vieno su savo mintimis.", "Mažinkite nereikalingą triukšmą.", "Užtikrinkite miegą ir poilsį, kai leidžia situacija – priežiūros darbus grupuokite.", "Kas kartą prieidami paklauskite apie skausmą, šaltį, troškulį."], "esme": ["Pacientas nėra tik trauma."], "klaidos": ["Apie sužeistąjį kalbama taip, lyg jis negirdėtų."], "vaizdai": [], "video": [], "saltiniai": ["Kuopos paskaita „Slauga taktinėje aplinkoje (PCC)“ (2026-09-21)"]},
  {"id": 25, "grupe": "W", "pav": "Žaizdų plovimas ir tvarsčių keitimas", "lygis": "CMC", "fazes": ["PAROS"], "aprasas": "Visos lauko žaizdos laikomos nešvariomis. Kuo ilgiau laukiama, tuo svarbesni plovimas, švarūs tvarsčiai ir kasdienė apžiūra.", "zingsniai": ["Nuskausminkite iš anksto: IV – 15–30 min, per burną – ≥ 60 min, vietinis anestetikas – 10–15 min prieš.", "Patraukite nuo purvo, nusiplaukite rankas, paruoškite švarų paviršių (#30).", "Skystis: geriausia – sterilus NaCl ar vanduo; geriau – švarus geriamasis vanduo; minimum – švariausias vanduo, virintas ≥ 3 min ir atvėsintas.", "Kiekis: maža ar švari – 1–3 l; vidutinė ar nešvari – 4–8 l; didelė ar labai nešvari – ≥ 9 l.", "Slėgis: 35 ml švirkštas su 19 G kateteriu (~8 psi) – mažoms; didelėms – IV maišas ar pylimas. Jodo, alkoholio ar antibiotikų į skystį nereikia.", "Negyvybingų audinių šalinimas – tik apmokytam (CPP), geriausia su telekonsultacija; nervų ir sausgyslių nešalinkite.", "Neužsiūkite: su audinių netekimu ir dūrines – atviros; abejojant – atvira. Uždelstas užsiuvimas – po 3–7 d., jei nėra infekcijos (gydytojas).", "Tvarstis: gilioms – NPWT (#26) ar drėgnas–sausas, keičiamas 1–2 kartus per dieną; minimum – storas sausas. Tikrinkite kas 24 val. (kritinei – kas 12 val.); permirkusį ar nešvarų keiskite.", "Spalva, išskyros, kvapas, skausmas – į lapą; nuotrauka telekonsultacijai."], "esme": ["Infekcija: didėjantis skausmas, paraudimas, pūliai; sisteminiai požymiai – karščiavimas, tachikardija, hipotenzija, sumišimas (#29)."], "klaidos": ["Lauko žaizda užsiuvama aklinai – abscesas, sepsis.", "Plaunama per mažu kiekiu ar per dideliu slėgiu."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Acute Traumatic Wound Management in PFC“ (tccc.org.ua, 2023)", "JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)"]},
  {"id": 26, "grupe": "W", "pav": "Improvizuotas neigiamo slėgio tvarstis (NPWT)", "lygis": "CPP", "fazes": ["PAROS"], "aprasas": "Neigiamo slėgio tvarstis – geriausias pasirinkimas gilioms ar didelėms žaizdoms, kai evakuacija vėluoja. Improvizuojamas iš marlės, skaidrios plėvelės ir siurbimo vamzdelio.", "zingsniai": ["Sprendžia CPP ar gydytojas, geriausia su telekonsultacija; kraujavimas sustabdytas.", "Žaizdą išplaukite ir sutvarkykite (#25).", "Užpildykite marle, į ją įdėkite perforuotą siurbimo vamzdelio galą.", "Sandariai uždenkite skaidria plėvele (Tegaderm, Ioban) su užlaida ant sausos sveikos odos.", "Prijunkite prie siurblio. Komercinis NPWT – 75–125 mm Hg nuolat; improvizuotam slėgis gairėse nenurodytas – pagal telekonsultaciją.", "Tvarstis turi susitraukti ir likti sandarus; nesandarias vietas užklijuokite.", "Keiskite kas 2–3 d., infekuotą – kasdien; kraujas vamzdelyje – stabdykite, vertinkite.", "Išskyrų kiekį ir spalvą – į lapą."], "esme": ["NPWT neplauna žaizdos – pirmiau plovimas ir nešvarumų pašalinimas."], "klaidos": ["Nesandarus tvarstis – siurbimas neveikia.", "Uždedama ant nesustabdyto kraujavimo."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Acute Traumatic Wound Management in PFC“ (tccc.org.ua, 2023)"]},
  {"id": 27, "grupe": "W", "pav": "Turniketo konversija PCC metu", "lygis": "CMC", "fazes": ["STAB", "VAL"], "aprasas": "Kiekvienas turniketas peržiūrimas: ar dar reikalingas ir ar galima jį pakeisti kitu kraujavimo stabdymo būdu. Po 2 val. didėja reperfuzijos ir hiperkalemijos rizika.", "zingsniai": ["Laikas, veiksmingumas, ar vis dar reikalingas.", "Konversija < 2 val., jei: nėra šoko, žaizdą galima stebėti, ne amputacija; kraujavimą stabdykite tamponavimu ir spaudžiamuoju tvarsčiu.", "Ant uniformos uždėtą keiskite nauju ant odos 5–7,5 cm virš žaizdos, tada senąjį atleiskite.", "2–6 val. – konversiją svarstykite: paruoškite kalcį, insuliną su gliukoze, EKG; telekonsultacija (#35).", "> 6 val. – nenuimkite, nebent yra stebėsena ir laboratorija.", "Atleistą turniketą palikite vietoje; stebėkite kraujavimą ir distalinį pulsą; laikus užrašykite.", "Po spaudžiamuoju tvarsčiu susilpnėjęs pulsas ar marmurinė oda – tvarstis veikia kaip veninis turniketas.", "Gyvybė svarbiau už galūnę: konvertuoti negalima – turniketas lieka, telekonsultacija."], "esme": ["Turniketo laiko nekeiskite – skaičiuojama nuo pirmojo uždėjimo."], "klaidos": ["Konvertuojama šoke ar negalint stebėti žaizdos.", "2–6 val. intervale nepasiruošiama hiperkalemijai."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "JTS CPG „Damage Control Resuscitation in PFC“ (ID 73, 2018)", "JTS CPG „Crush Syndrome in PFC“ (tccc.org.ua, 2023)", "TCCC gairės 2026-05-01"]},
  {"id": 28, "grupe": "W", "pav": "Įtvarų patikra ir kompartmento sindromas", "lygis": "CLS", "fazes": ["VAL", "PAROS"], "aprasas": "Tinimas didėja 2–5 paras, todėl įtvaras, kuris tiko pirmą valandą, vėliau gali spausti. Kompartmento sindromą pirmiausia išduoda skausmas.", "zingsniai": ["Distalinis pulsas: sąmoningam – ne rečiau kaip kas 6 val.; be sąmonės – kas 2 val.", "Klauskite: ar skauda įtvaras, ne lūžis? Tikrinkite spaudimą, tirpimą, šilumą, kapiliarų prisipildymą (2–3 s), odą po juostele.", "Įtvaras – vienas sąnarys virš ir žemiau lūžio; nepasislinkęs, neužveržtas.", "Kompartmento sindromas: skausmas, ypač didėjantis ar judinant pasyviai; vėliau – tirpimas, blyškumas, paralyžius, pulso nebuvimas.", "Įtarus – atlaisvinkite įtvarą ir vertinkite; neišnyksta – nuimkite, skubiai medikas ir telekonsultacija (fasciotomija – tik apmokytam).", "Nekalbantis ar sedatuotas – stebėkite dažniau.", "Kol laukiama – vėsinkite garinimu ar aplinka, ne ledu ar sniegu."], "esme": ["Pulsas išnyksta vėlai – jo buvimas kompartmento sindromo neatmeta."], "klaidos": ["Skausmas malšinamas vis didesnėmis dozėmis, o galūnė neapžiūrima."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "JTS CPG „Crush Syndrome in PFC“ (tccc.org.ua, 2023)"]},
  {"id": 29, "grupe": "W", "pav": "Antibiotikai ir infekcijos požymiai", "lygis": "CMC", "fazes": ["STAB", "PAROS"], "aprasas": "Atvirai kovinei žaizdai antibiotikas skiriamas kuo anksčiau ir kartojamas laiku. Antibiotikas nepakeičia plovimo ir nešvarumų pašalinimo.", "zingsniai": ["TCCC 2026: gali nuryti – cefadroksilis; negali – ceftriaksonas IV / IO / IM (Vaistai).", "Kitą dozę – laiku; laiką rašykite į lapą (#3).", "Nudegimams be kitų žaizdų profilaktiškai nereikia (#33).", "Atvira galvos trauma, suspaudimo sindromas, labai nešvari žaizda, alergija – vaistą ir trukmę parenka gydytojas (ertapenemas, cefazolinas, moksifloksacinas).", "Kasdien: vietiniai požymiai – skausmas, paraudimas, pūliai, kvapas; sisteminiai – karščiavimas, tachikardija, hipotenzija, sumišimas.", "Įtarus infekciją – žaizdą atverti, išplauti, telekonsultacija; gydymas 7–10 d. (gydytojas).", "Stabligė: neskiepytas ar nežinoma – Tdap ir TIG pagal gydytoją."], "esme": ["Negyjanti per 2 sav. žaizda – infekcija, prasta perfuzija ar mityba."], "klaidos": ["Pamirštama kita dozė.", "Paraudimas aplink žaizdą laikomas „normaliu“."], "vaizdai": [], "video": [], "saltiniai": ["TCCC gairės 2026-05-01", "JTS CPG „Acute Traumatic Wound Management in PFC“ (tccc.org.ua, 2023)", "JTS CPG „Burn Wound Management in PFC“ (tccc.org.ua, 2023)", "JTS CPG „TBI Management in PFC“ (tccc.org.ua, 2023)"]},
  {"id": 30, "grupe": "W", "pav": "Aseptika ir infekcijų kontrolė lauke", "lygis": "CLS", "fazes": ["VAL", "PAROS"], "aprasas": "Kuo ilgiau laukiama evakuacijos, tuo didesnė infekcijos rizika. Švarus ≠ sterilus; rankų dezinfekcija nepakeičia plovimo.", "zingsniai": ["Rankų higiena prieš ir po kiekvieno kontakto; kiekvienam sužeistajam – naujos pirštinės.", "Atskirkite švarią ir nešvarią zoną; tvarstymui – švarus paviršius, toliau nuo purvo.", "Kateteris, IV, vamzdelio atsiurbimas – sterili technika.", "Pradėti švirkštai – tik vienam sužeistajam, paženklinti, po 24 val. išmesti.", "Vanduo plovimui ir gėrimui: abejojate – virinkite ≥ 3 min.", "Aštrūs daiktai – į talpą; biologinės atliekos – atskirai pagal SOP.", "Įsidūrus panaudota adata – praneškite (hepatitas B, C, ŽIV)."], "esme": ["Instrumentus, jei nėra kito būdo, galima virinti."], "klaidos": ["Tos pačios pirštinės keliems sužeistiesiems.", "Švirkštas naudojamas keliems pacientams."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Nursing Interventions, Wound Care, and Splint Management in PCC“ (ID 70, 2025)", "JTS CPG „Acute Traumatic Wound Management in PFC“ (tccc.org.ua, 2023)", "Kuopos paskaita „Bendrieji higienos ir infekcijų kontrolės principai“ (2026)"]},
  {"id": 31, "grupe": "Y", "pav": "Hipotermija ir perkaitimas ilgalaikėje priežiūroje", "lygis": "CLS", "fazes": ["STAB", "VAL", "PAROS", "EVAK"], "aprasas": "Hipotermija blogina krešėjimą ir didina mirtingumą nuo kraujavimo; ją lengviau išvengti nei gydyti. Karštyje – priešinga rizika: perkaitimas.", "zingsniai": ["Izoliuokite nuo žemės, šlapius drabužius keiskite sausais, uždenkite su galva, saugokite nuo vėjo ir drėgmės.", "Aktyvus šildymas – ant krūtinės priekio ir pažastų, niekada tiesiai ant odos ar spaudžiamų vietų.", "Šildanti antklodė (Ready-Heat) – keisti po > 10 val.", "Temperatūra: minimum – pagal grafiką; geriau – nuolatinis kaktos indikatorius; geriausia – nuolatinė vidinė.", "Skysčius ir kraują – per šildytuvą (iki 150 ml/min, 38 °C).", "Nudegusiam – tikėkitės hipotermijos; < 36 °C – aktyviai šildykite (#33).", "Perkaitimas: pavėsis, nuimti šalmą ir liemenę, vėdinti; karščio smūgis – skubus vėsinimas (šlapinti ir vėdinti, geriausia – panardinti). Paracetamolio ir NVNU perkaitimui neskirti."], "esme": ["Kraujavimas + hipotermija + acidozė – mirtina triada."], "klaidos": ["Šildymo paketas tiesiai ant odos – nudegimas.", "Atidengus apžiūrai – neuždengiama atgal."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "JTS CPG „Burn Wound Management in PFC“ (tccc.org.ua, 2023)", "TCCC gairės 2026-05-01"]},
  {"id": 32, "grupe": "Y", "pav": "Galvos smegenų trauma PCC metu", "lygis": "CMC", "fazes": ["VAL", "YPAT"], "aprasas": "Galvos traumos baigtį blogina antrinis pažeidimas – hipoksija ir hipotenzija. PCC metu svarbiausia: tikslai, neurologinė patikra kas valandą, ankstyva telekonsultacija.", "zingsniai": ["GKS ir vyzdžiai – ne rečiau kaip kas valandą; užrašykite prieš kiekvieną sedaciją.", "Galvūgalis 30–60° (jei nėra šoko), kaklas tiesiai; malšinkite skausmą, nerimą, karščiavimą.", "Tikslai: SpO₂ ≥ 92 % (ventiliuojamam > 95 %); sAKS > 110 mm Hg; ventiliuojamam EtCO₂ 35–40 mm Hg; temperatūra 35,6–37,5 °C; gliukozė ~10 mmol/l (< 5,6 – gydyti).", "Išvaržos požymiai (vienpusis išsiplėtęs vyzdys, patologinė laikysena, Cushing triada) – hipertoninis NaCl, skubi telekonsultacija; laikinai EtCO₂ 30 mm Hg ≤ 20 min.", "Traukuliai – midazolamas; toliau – levetiracetamas (gydytojas) (Vaistai).", "Atvira galvos žaizda ar kaukolės lūžis – antibiotikas (gydytojas) (#29).", "Sedaciją ir analgeziją minimizuokite, kiek įmanoma.", "Blogėja GKS ar vyzdžiai – didinkite evakuacijos skubumą, telekonsultacija su neurochirurgu."], "esme": ["Vienas hipoksijos ar hipotenzijos epizodas blogina baigtį.", "JTS TBI PFC: SpO₂ > 90 % (ventiliuojamam > 95 %), sAKS > 110; TCCC 2026 (TFC): SpO₂ ≥ 92 %, sAKS > 100.", "Hiperventiliacija – tik gresiant išvaržai, trumpai."], "klaidos": ["Hiperventiliuojama „profilaktiškai“.", "Neurologinė patikra neužrašoma – blogėjimas nepastebimas."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „TBI Management in PFC“ (tccc.org.ua, 2023)", "JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "TCCC gairės 2026-05-01"]},
  {"id": 33, "grupe": "Y", "pav": "Nudegimai PCC metu: skysčiai ir žaizdos", "lygis": "CMC", "fazes": ["YPAT"], "aprasas": "Nudegęs pirmiausia yra traumos pacientas. > 20 % KPP ar įkvėpimo trauma – gyvybei pavojinga; skysčiai titruojami pagal diurezę, ne pagal formulę.", "zingsniai": ["Plotas – tik II ir III laipsnio: devynių taisyklė arba delnas su pirštais ≈ 1 %.", "IV / IO iš karto; kol vertinate – 500 ml/val.", "10 taisyklė: KPP % × 10 = ml/val. (40–80 kg); +100 ml/val. kiekvienam 10 kg virš 80. Boliusas – tik esant hipotenzijai; „vytis“ nevėluokite.", "Diurezė 30–50 ml/val. (elektros trauma, rabdomiolizė – 70–100); greitį keiskite ±25 % kas 1–2 val. Be kateterio – > 180 ml per 6 val.", "Iki ~30 % ir gali gerti – elektrolitų tirpalas pagal grafiką; tik vanduo – hiponatremija.", "Sunki įkvėpimo trauma ar > 40 % – intubacija (CPP); supraglotinės priemonės netinka.", "Žaizdos: geriausia – kasdien nuplauti chlorheksidinu, sidabro kremas (sulfadiazinas) ar mafenidas, marlė (arba Silverlon 3–5 d.); minimum – švari paklodė ar sausa marlė, pūslių nepradurti.", "Hipotermija – tikėtina visiems: uždenkite, < 36 °C – aktyviai šildykite.", "Skausmas: dažnos mažos ketamino dozės IV; prieš tvarstymą – iš anksto.", "Žiedinis gilus nudegimas krūtinėje ar galūnėje – eskarotomija (#34)."], "esme": ["Klaida > 10 % vertinant plotą žalinga abiem kryptimis.", "Antibiotikų profilaktiškai nereikia, nebent yra kitų atvirų žaizdų."], "klaidos": ["Skaičiuojamas ir I laipsnio nudegimas.", "Greitis nekeičiamas pagal diurezę."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Burn Wound Management in PFC“ (tccc.org.ua, 2023)"]},
  {"id": 34, "grupe": "Y", "pav": "Eskarotomija: kada ir kaip pasiruošti", "lygis": "CPP", "fazes": ["YPAT"], "aprasas": "Žiedinis gilus nudegimas veikia kaip turniketas: krūtinėje trukdo kvėpuoti, galūnėje sustabdo kraujotaką. Atlieka apmokytas CPP ar gydytojas, kai įmanoma – su telekonsultacija.", "zingsniai": ["Krūtinė – įtemptas žiedinis gilus nudegimas, trukdantis kvėpuoti.", "Galūnė – žiedinis gilus nudegimas su silpnėjančiu ar išnykusiu distaliniu pulsu, kai evakuacija vėluoja.", "Prieš tai atmeskite kitas priežastis: pneumotoraksas, per stipriai užveržtas tvarstis, skausmas.", "Pasiruoškite: nuskausminimas ir sedacija (#17), sterilus rinkinys, hemostatiniai tvarsčiai.", "Pjūvis – per nudegusį audinį iki riebalų; galūnėje – per pažeistus sąnarius (technika – pagal telekonsultaciją).", "Tikėkitės kraujavimo ir skausmo; po procedūros – pulsas ir kvėpavimas.", "Tvarstykite kaip nudegimą (#33); laiką ir rezultatą užrašykite."], "esme": ["Vaizdo telekonsultacija labiausiai naudinga būtent tokioms procedūroms."], "klaidos": ["Pjaunama nepasiruošus kraujavimui."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Burn Wound Management in PFC“ (tccc.org.ua, 2023)", "JTS CPG „Telemedicine Guidance in the Deployed Setting“ (ID 94, 2023)"]},
  {"id": 35, "grupe": "Y", "pav": "Suspaudimo sindromas ir hiperkalemija", "lygis": "CMC", "fazes": ["YPAT", "STAB"], "aprasas": "Po ilgo prispaudimo ar ilgai laikyto turniketo atsilaisvinus išsiskiria kalis ir mioglobinas: aritmijos ir inkstų pažeidimas. Valdymas sudėtingas – telekonsultacija kuo anksčiau.", "zingsniai": ["Rizika: prispausta ≥ 1 val.; turniketas > 2 val.; kompartmento sindromas; sunki buka galūnės trauma.", "Prieš išlaisvinimą: IV / IO kristaloidai – 2 l boliusas, toliau 1 l/val.; hipotenzinio gaivinimo principas netaikomas (jei nėra nesustabdomo kraujavimo).", "Nėra IV – elektrolitų tirpalas per burną pagal grafiką; minimum – per tiesiąją žarną iki 500 ml/val.", "Prispausta > 2 val. ir gydymo pradėti negalima – du turniketai greta virš sužalojimo prieš išlaisvinimą.", "Diurezė 100–200 ml/val.; žemiau tikslo > 2 val. esant 1 l/val. – inkstai pažeisti, telekonsultacija.", "EKG: bradikardija, smailūs T, ilgėjantis PR, platus QRS, ekstrasistolės; normali EKG hiperkalemijos neatmeta. Kas 15 min pirmas 1–2 val., toliau kas 30 min, stabiliai – kas valandą.", "Gydymas: kalcis (10 ml 10 % gliukonato per 2–3 min) → insulinas su gliukoze → salbutamolis purkštuvu (Vaistai); kartoti pagal poreikį.", "Galūnė šalta, nejautri, įtempta, be pulso – greičiausiai negyvybinga: du turniketai lieka, telekonsultacija."], "esme": ["Tik vanduo per burną – hiponatremija; naudokite ORS."], "klaidos": ["Išlaisvinama be skysčių ir neparuošus kalcio.", "Hiperkalemija atmetama, nes EKG „normali“."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Crush Syndrome in PFC“ (tccc.org.ua, 2023)", "JTS CPG „Damage Control Resuscitation in PFC“ (ID 73, 2018)"]},
  {"id": 36, "grupe": "E", "pav": "Telekonsultacija", "lygis": "CLS", "fazes": ["STAB", "VAL"], "aprasas": "Pagalbos prašymas – geroji praktika, kai evakuacija neaiški ar neįmanoma. Skambinkite anksti ir dažnai; telekonsultacija nepakeičia evakuacijos.", "zingsniai": ["Kada: neaiški diagnozė ar gydymas, būklė viršija įgūdžius ar išteklius. Skubu: šoko indeksas > 1, kvėpavimo nepakankamumas, sepsis, sutrikusi sąmonė, sunki galvos trauma.", "Skambina komandos narys – medikas nepalieka blogėjančio sužeistojo.", "Prieš skambutį nusiųskite: stebėjimo lapą, santrauką, žaizdų ir viso paciento nuotraukas (0,5–1 MB, be blykstės, su mastelio objektu).", "Pradžia: realus atvejis ar treniruotė, kokio specialisto reikia, atgalinio ryšio numeris.", "Pagal scenarijų: santrauka (amžius, lytis, mechanizmas, laikas nuo traumos), sužalojimai, gydymas, anamnezė ir alergijos, prašymas, rodiklių tendencijos, apžiūra pagal sistemas, skysčiai ir diurezė, ištekliai.", "Rekomendacijas užsirašykite ir pakartokite; neaiškumus klauskite iš karto.", "Atviru kanalu – tik lytis ir amžius, vietovė bendrai; be veido, tatuiruočių; geožymos išjungtos.", "Ryšio PACE planas; tikėkitės kelių pokalbių."], "esme": ["Balso dažniausiai pakanka; vaizdas – procedūroms."], "klaidos": ["Skambinama neturint duomenų – ilgas, neproduktyvus pokalbis.", "Medikas palieka sužeistąjį skambinti."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Telemedicine Guidance in the Deployed Setting“ (ID 94, 2023)", "PFC Documentation: Telemedical Consultation Guide (2023)"]},
  {"id": 37, "grupe": "E", "pav": "Pasiruošimas evakuacijai ir skrydžiui", "lygis": "CLS", "fazes": ["EVAK"], "aprasas": "Evakuacija prasideda dar prieš pačią evakuaciją. Sužeistasis paruošiamas taip, kad kelionė – ir ilgesnė nei planuota – būtų saugi.", "zingsniai": ["Evakuacijos prašymą teikite perimdami sužeistąjį; skubumą peržiūrėkite keičiantis būklei (9-Line).", "Prieš išvykimą – pilnas pakartotinis vertinimas; turniketai, tvarsčiai, linijos, vamzdeliai, kateteris – pritvirtinti.", "Vaistai, skysčiai, kraujas, deguonis, baterijos – su atsarga vėlavimui.", "Hipotermija: izoliacija, šildymas, vėjo ir drėgmės apsauga (#31).", "Neštuvai: diržai ne ant lūžių, paminkštinimas, akių ir ausų apsauga; turniketai matomi.", "Skrydis: krentant slėgiui plečiasi dujos (pneumotoraksas, manžetės, balionėliai), didėja hipoksija; vibracija, triukšmas, šaltis.", "Dokumentai kartu; perdavimas paruoštas (#38). Ginklas ir jautrūs daiktai – pagal SOP."], "esme": ["Po kiekvieno perkėlimo – trumpas MARCH."], "klaidos": ["Linijos ištraukiamos perkeliant.", "Neužtenka deguonies ar vaistų vėluojančiai kelionei."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "PFC WG „10 Essential Core Capabilities for PFC“ (2015)", "Kuopos paskaita „Slauga taktinėje aplinkoje (PCC)“ (2026-09-21)", "TCCC gairės 2026-05-01"]},
  {"id": 38, "grupe": "E", "pav": "Perdavimas ir dokumentai", "lygis": "CLS", "fazes": ["EVAK"], "aprasas": "Perdavimas – kas buvo, kas padaryta, kas pasikeitė, ko reikia. Po kelių parų priežiūros informacijos daug – perduokite struktūruotai ir raštu.", "zingsniai": ["Tiesiogiai priimančiam medikui: MIST (ar ATMIST) – mechanizmas ir laikas, sužalojimai, požymiai ir tendencijos, gydymas.", "Pirmiausia – kas tęstina: turniketų laikai, paskutinės dozės ir kitų laikas, infuzijos ir greičiai, alergijos.", "Skysčių balansas ir diurezė per 24 val.; problemų sąrašas, ko reikia toliau.", "Telekonsultacijų rekomendacijos ir neatlikti darbai.", "Kortelė DD 1380 ir stebėjimo lapas – kartu su sužeistuoju.", "Atsakykite į klausimus prieš išvykdami.", "Perpylus šviežią kraują – donoras ir gavėjas registruojami pagal SOP.", "Po užduoties – AAR ir priemonių papildymas."], "esme": ["Sužeistasis perduotas, kai priimantis perėmė stebėseną."], "klaidos": ["Perduodama tik žodžiu, be laikų.", "Neperduoti infuzijų greičiai ir dozių laikai."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Prolonged Casualty Care Guidelines“ (ID 91, 2021)", "JTS CPG „Damage Control Resuscitation in PFC“ (ID 73, 2018)", "Kuopos paskaita „Slauga taktinėje aplinkoje (PCC)“ (2026-09-21)"]},
  {"id": 39, "grupe": "E", "pav": "Mirštančio sužeistojo priežiūra", "lygis": "CMC", "fazes": ["PAROS"], "aprasas": "Kai kurie sužalojimai be chirurgijos neišgyvenami. Sprendimas nutraukti gaivinimą nereiškia priežiūros pabaigos: skausmas ir kančia malšinami iki galo.", "zingsniai": ["Prieš nutraukiant gaivinimą – bandykite susisiekti su medicinos vadovybe (telekonsultacija).", "Nepavyksta – sprendžia vietoje esantis medikas: ištekliai, evakuacijos laikas, kitų sužeistųjų poreikiai.", "Malšinkite skausmą ir nerimą, nepagreitindami mirties (jokių mirtinų dozių).", "Agoninis kvėpavimas ir judesiai – galimi; paaiškinkite draugams, tai ne priežastis tęsti gaivinimą.", "Mirus – intervencijas palikite vietoje; trūkstant priemonių – galima panaudoti iš naujo.", "Mirusio kraujo perpylimui neimkite.", "Pasirūpinkite komanda: aptarimas, poilsis, parama."], "esme": ["Ne visada įmanoma išgelbėti visus – tai karo medicinos realybė, ne asmeninė nesėkmė."], "klaidos": ["Gaivinimas tęsiamas be vilties, eikvojant išteklius kitiems.", "Paliekama be nuskausminimo."], "vaizdai": [], "video": [], "saltiniai": ["JTS CPG „Damage Control Resuscitation in PFC“ (ID 73, 2018) – gyvenimo pabaigos priežiūra", "JTS CPG „Analgesia and Sedation Management during PFC“ (tccc.org.ua, 2023)"]}
];
